package com.cinema4d.app.data.model

import kotlinx.serialization.Serializable

/**
 * Mirrors assets/seat_map.json — generated by tools/build_hall.py from the
 * Blender auditorium. Positions are in glTF space (meters, +Y up, screen at +Z).
 */
@Serializable
data class SeatMapDocument(
    val hall: HallInfo = HallInfo(),
    val rows: List<RowInfo> = emptyList(),
    val aisleHalf: Float = 0.55f,
    val seats: List<SeatInfo> = emptyList(),
)

@Serializable
data class HallInfo(
    val width: Float = 14.4f,
    val depth: Float = 20.6f,
    val screen: ScreenInfo = ScreenInfo(),
)

@Serializable
data class ScreenInfo(
    val y: Float = 0f,
    val z: Float = 0f,
    val w: Float = 0f,
    val h: Float = 0f,
    val center: List<Float> = emptyList(),
)

@Serializable
data class RowInfo(
    val letter: String = "",
    val y: Float = 0f,
    val floorZ: Float = 0f,
    val perSide: Int = 0,
    val recliner: Boolean = false,
)

@Serializable
data class SeatInfo(
    val id: String,
    val row: String = "",
    val num: Int = 0,
    val x: Float = 0f,
    val mapY: Float = 0f,
    val eye: List<Float> = emptyList(),
    val pos: List<Float> = emptyList(),
    val tier: String = "classic",
) {
    val rowLabel: String get() = row
    val seatLabel: String get() = "$row$num"
}
